if(a==='print-finish'){if(o.op!=='印花'||!['印制中','转印中'].includes(b.stage)||!number('qty',true))return fail('核对当前步骤及实际完成数量。');const q=N('qty'),printing=b.stage==='印制中',limit=printing?b.input:b.printQty,prior=printing?(b.printQty||0):(b.transferQty||0);if(q<=prior||q>limit+.001)return fail('累计完成须增加，且不能超过本步实际投入。');if(printing)b.printQty=q;else b.transferQty=q;event(printing?'印制完成':'转印完成',qtext(q));b.stage=printing&&o.transfer?'待转印':'待填报产出';fresh();return ok('工序完成已记录。');}
if(a==='print-output'){if(o.op!=='印花'||b.stage!=='待填报产出'||!number('qty'))return fail('填写本次新增合格产出。');const q=N('qty'),loss=v('loss').trim()?N('loss'):undefined,limit=o.transfer?b.transferQty:b.printQty;if(loss!==undefined&&!number('loss',true))return;if((b.output||0)+q>limit+.001||(b.output||0)+q+(b.loss||0)+(loss||0)>b.input+.001)return fail('产出不能超过工序完成量，产出与损耗不能超过实际投入。');b.output=round((b.output||0)+q);b.loss=round((b.loss||0)+(loss||0));b.lossUnknown=!!b.lossUnknown||loss===undefined;b.unmeasuredOutput=q;b.stage='待逐卷实测';s.view='out';event('填报加工产出',qtext(q)+' · '+(loss===undefined?'损耗未核算':qtext(loss)));fresh();return ok('本次产出已记录。');}
