if(a==='dye-sample'){if(!guard('dye'))return;const o=O();if(o.op!=='染色'||o.sample)return fail('本单色样已完成，无须重复。');if(!o.sampleStarted){o.sampleStarted=true;event('开始打样',o.colorNo);fresh();return ok('已开始本单打样，完成时在本页确认。');}o.colorNo=v('colorNo').trim()||o.colorNo;if(!o.colorNo)return fail('核对实际色号。');o.sample=true;event('完成打样',o.colorNo);fresh();return ok('色样已记录，继续本单实际原料领入。');}if(a==='receive')return saveReceive();if(a==='input')return saveInput();if(['artwork','sample','water','water-dye','dye-step','transfer','print-finish','print-output','wash-output'].includes(a))return saveStep(a);if(a==='roll-save')return saveRolls();if(a==='to-rolls'){s.view='out';render();return;}if(a==='roll-add'||a==='roll-remove'){s.form.rollCount=Math.max(1,Math.min(20,(s.form.rollCount||1)+(a==='roll-add'?1:-1)));dirty=true;render();return;}if(a==='out')return send();if(a==='judge-save')return judgeSave();if(a.startsWith('pick:')){const code=a.slice(5);s.selected=s.selected.includes(code)?s.selected.filter(x=>x!==code):[...s.selected,code];s.scanSet=s.scanSet.filter(x=>s.selected.includes(x));dirty=true;render();return;}
if(a==='label'){if(!picked().length)return fail('先选择实际产出卷。');s.previewCodes=picked().map(r=>r.code);sheet('本批卷标签预览',picked().map(r=>panel(kv('原加工单',O().id)+kv('批次',r.batch)+kv('卷码',r.code)+kv('实测数量',qtext(r.qty,r.unit)))).join('')+note('设计预览未连接打印机。贴标状态须按现场实际核对。','info'),btn('标签已贴好，继续核对','label-done','primary'));return;}if(a==='label-done'){if(!guard(O().op==='洗水'?'wash':'store'))return;if(!(s.previewCodes||[]).length||(s.previewCodes||[]).some(code=>!realRoll(code)||realRoll(code).sent))return fail('卷已变化，重新核对。');for(const code of s.previewCodes)realRoll(code).label=true;event('核对已贴卷标签',(s.previewCodes||[]).join('、'));closeSheet();s.notice='标签已核对，逐卷扫描本次实物。';dirty=false;render();return;}
if(a.startsWith('input-label:')){const r=s.sources.find(r=>r.id===a.slice(12));if(!r||r.order!==s.order||r.received===null)return fail('仅可查看本单实际接收卷标签。');sheet('投入卷标签预览',panel(kv('卷码',r.code)+kv('原实收',qtext(r.received,r.unit))+kv('库位',r.location))+note('沿用原卷码；补打不新增接收或库存。','info'));return;}
if(a==='correct'){if(!guard('judge'))return;const ps=picked();if(ps.some(r=>r.sent)||s.fixtures.reserved)return fail('只可纠正未交出且未占用的卷。已送洗的先核对原单。');const affected=[...new Set(ps.map(r=>r.washingOrder).filter(Boolean))];if(affected.some(id=>s.orders[id].expectedCodes.some(code=>!ps.some(r=>r.code===code))||s.sources.some(r=>r.order===id)))return fail('须选齐原洗水单全部卷；已经交出则由跟单协调原单。');for(const id of affected)s.orders[id].cancelled=true;for(const p of ps){const r=realRoll(p.code);delete r.washingOrder;(r.judgmentHistory??=[]).push({decision:r.decision,feel:r.feel,actor:r.judge,time:r.judgedAt});delete r.decision;delete r.feel;}event('纠正触摸结果',ps.map(r=>r.code).join('、'));fresh();ok('原结果已留痕，重新登记本次手感。');return;}
if(a==='sample-view'){sheet('本单色样',productBlock()+kv('本单色号',O().colorNo));return;}if(a==='zero-records'){sheet('本单零产出核对',panel(kv('本单',O().id)+kv('累计投入',qtext(sum(O().batches.map(b=>b.input))))+kv('累计产出',qtext(0)))+O().batches.map(b=>panel(kv('批次',b.id)+kv('投入 / 产出',qtext(b.input)+' / '+qtext(b.output)))).join('')+s.events.filter(e=>e.order===s.order).map(e=>'<p>'+esc(e.action+' · '+e.detail)+'<br>'+esc(e.actor+' · '+e.time)+'</p>').join(''));return;}
