function review(){const hs=s.hands.filter(h=>!h.nextOrder&&h.actual===null),selected=hs.find(h=>h.id===s.externalChoice)||hs[0];return `<div id="dpw-review" class="note-box"><b>V11 评审工具 · 不属于 PDA</b><label>查看关联工序<select id="dpw-op">${OPS.map(x=>`<option ${x===selectedOp?'selected':''}>${x}</option>`).join('')}</select></label><p>染色→印花、印花→洗水的实收在相应工序登记；下列仅模拟外部最终接收方。</p>${hs.length?`<label>外部待实收单<select id="dpw-external">${hs.map(h=>`<option value="${h.id}" ${h===selected?'selected':''}>${h.id} · ${h.target} · ${qtext(h.qty,h.unit)}</option>`).join('')}</select></label>${selected.rows.length===1?'<label>接收方实际数量<input id="dpw-actual" inputmode="decimal"></label>':selected.rows.map((r,i)=>'<label>'+esc(r.code+' 实收 · '+r.unit)+'<input id="dpw-actual-'+i+'" inputmode="decimal"></label>').join('')}${btn('模拟原接收方实收','review-actual')}`:''}<p id="dpw-review-message">${esc(s.reviewMessage)}</p><details><summary>边界条件样例</summary><label><input type="checkbox" id="dpw-factory" ${s.fixtures.factory?'checked':''}>当前本厂</label><label><input type="checkbox" id="dpw-source" ${s.fixtures.source?'checked':''}>来源有效</label><label><input type="checkbox" id="dpw-target" ${s.fixtures.target?'checked':''}>接收方已明确</label><label><input type="checkbox" id="dpw-spec" ${s.fixtures.spec?'checked':''}>规格与图片完整</label><label><input type="checkbox" id="dpw-reserved" ${s.fixtures.reserved?'checked':''}>实物被其他交出单占用</label></details><p>仅页面内存，刷新重置。扫码、贴标、岗位均为可点击设计演示。</p></div>`;}
function reviewAction(a){const bad=t=>{$('#dpw-review-message').textContent=t;};if(dirty)return bad('先提交或放弃 PDA 未保存输入。');if(scenario!=='normal')return bad('外部结果未保存，原事实保留。');const h=s.hands.find(h=>h.id===$('#dpw-external')?.value);if(!h||h.actual!==null||h.nextOrder)return bad('仅原接收方可登记尚未实收的交出。');const quantities=h.rows.map((r,i)=>{const text=$(h.rows.length===1?'#dpw-actual':'#dpw-actual-'+i).value.trim();return text===''?NaN:Number(text)}),q=sum(quantities);if(quantities.some((n,i)=>!Number.isFinite(n)||n<=0||n>h.rows[i].qty||Math.abs(n*1000-Math.round(n*1000))>.00001))return bad('逐卷实收须大于 0 且不超过本次交出，保留原单位。');h.actual=q;h.receiver=h.target+' · 接收员 Dewi';h.location=h.target+' A01';h.receivedAt=now();h.rows.forEach((r,i)=>Object.assign(r,{actual:quantities[i],receiver:h.receiver,location:h.location,receivedAt:h.receivedAt}));event('原接收方实收',h.id+' · '+qtext(q,h.unit),h.receiver);s.notice='接收方实收样例已登记，可在本单查看。';render();}
